import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { load } from 'cheerio'; // Changed from default import to named import

const ContentFetcher = ({ baseUrl, divId, number, renderContent }) => { // Added renderContent to props
  const [content, setContent] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchContent = async () => {
      setLoading(true);
      setError(null);

      try {
        const fetchedContent = [];
          const url = `${baseUrl}${number}`;
          const response = await axios.get(url, {
            headers: {
              'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36',
            },
          });
          const $ = load(response.data); // Changed from cheerio.load to load
          const divContent = $(`#${divId}`).html();

          if (divContent) {
            fetchedContent.push({ url, content: divContent });
          }
        setContent(fetchedContent);
      } catch (err) {
        setError(err.message); // Store just the error message
      } finally {
        setLoading(false);
      }
    };

    fetchContent();
  }, [baseUrl, divId, lastNumberRange]);

  if (loading) {
    return <div>Loading...</div>;
  }

  if (error) {
    return <div>Error: {error}</div>; // Now using error directly
  }

  // Only call renderContent if it exists and we have content
  if (renderContent && content.length > 0) {
    return renderContent(content);
  }

  // Default return when no content
  return <div>No content found</div>;
};

export default ContentFetcher;
